//! Shared test support for `dpds-controller` (included with `mod common;`).
//!
//! One integration-test binary (`tests/integration/main.rs`), submodules per topic; no lint
//! suppressions, every helper here is used by some test. Tests go through HTTP and JSON wherever
//! possible. The fake sysfs/procfs trees are generated by [`FakeHost`] (code, not checked-in
//! files, so every test can vary one knob).
//!
//! The controller stores nothing. Rust items the tests touch: `api::{router, router_with, Deps}`
//! (`Deps` points at no directory the controller writes), `model::Link`, `eal::{eal_argv,
//! EalInput, EalPort, links_file_json, drain_timeout}` and `dto::ConfigDto` (`to_core()` validates
//! and maps). `hints::compute_hints` and `lcores::assign_lcores` are reached through
//! `POST /api/host/hints` and `POST /api/emulation/validate` ([`hints_json`], [`plan_for`]).
//!
//! `dpds-controller serve|check`: `check` takes `--sysfs-root --procfs-root --ifaddrs-file --etc-dir
//! --json` only (the host flags are test-only and shared with `serve`; `--etc-dir` names the
//! directory with the stored mode file `network`); `--state-dir` is a usage error (exit 2) for both. Both read the stored
//! network mode first and exit 2 without one: every test that starts the binary gets the physical
//! one through [`controller_cmd`] / [`ControllerProcess`], or its own `--etc-dir`.
//!
//! The network mode (`host::Network`, `Physical` or `Virtual`) is `HostRoots::network`, built from
//! the stored file by the binary and set by [`FakeHost`] (`FakeHost::virtual_net`).
//!
//! `check` text mode prints one line per hint with the upper-case level and the
//! title; exit 1 iff any hint has level error.
//!
//! # HTTP contract
//!
//! - `POST /api/emulation/start` body (`StartRequest`, `deny_unknown_fields` at every level):
//!   `{"links": [{name, ingress, egress, config}]}`; `settings`, `worker` and a link `id` are 400s
//!   naming the field. 202 with the `/api/emulation` body; non-JSON content type 415 (checked
//!   first); malformed or unknown fields 400; empty `links` 400 "nothing to start"; while
//!   starting/running/stopping 409; names, ports, port reuse (409), uplink (409), the dict limit
//!   (400 naming 256), the lcore plan (400) and `initialization_rate_pps` are validated. Nothing is
//!   spawned on an error.
//! - `GET /api/emulation`: `{state, pid, started_at, directions, main_lcore, error, log_tail,
//!   config}`. While stopped `config` is null/absent, `directions` `[]`, `main_lcore` null/absent.
//!   Otherwise `config` = `{links: [{id, name, ingress, egress, config}]}`, the start body as
//!   accepted (PCI addresses in lower case, ids unique, order kept), and `directions`/`main_lcore`
//!   are the planned lcores.
//! - `POST /api/emulation/validate`: same body and errors as start (but no state check, no
//!   telemetry-build check, nothing spawned); 200 `{"main_lcore": n, "directions":
//!   [{dir, link, rx, tx, lcore}]}`.
//! - `GET /api/host/hints`: host-only hints. `POST /api/host/hints` with a StartRequest body: the
//!   same plus the link-dependent ones (`HINT_IDS`, `uplink`, `drain_timeout`, the per-NIC ids of
//!   [`nic_id`]); an empty `links` list gives the host-only hints. A hint may have `commands:
//!   [string]` (omitted when empty); none has an `action`; see `host_commands.rs`.
//! - `/api/links*`, `/api/presets*`, `/api/settings`, `/api/export`, `/api/import` are 404
//!   (unknown path) or 405 (known path, wrong method).
//!
//! # Optional stages
//!
//! `ConfigDto.delayer`, `.limiter` and `.loss_model` are optional (absent or `null` = not added);
//! `limiter.activate` is an unknown field (400), a present limiter is active. A missing stage maps
//! to a no-op `dpds_core::Config` stage: delayer `Deterministic`, mean 0, std 0, no correlation,
//! half-life 0, `initialization_rate_pps` 1; limiter `Spacer`, `activate: false`, `rate_bps` 0;
//! loss model `Random(0)`. A present stage requires and validates all its fields.

use std::fs;
use std::net::{IpAddr, TcpStream};
use std::path::PathBuf;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

use serde_json::{json, Value};
use tempfile::TempDir;

use dpds_controller::api::{self, Deps};
use dpds_controller::dto::ConfigDto;
use dpds_controller::host::{CommandOutput, Exec, HostRoots, IfAddrs, Network};
use dpds_controller::model::Link;
use dpds_controller::stats::{Polled, Snapshot};
use dpds_controller::supervisor::{LaunchPlan, State, Supervisor, SupervisorStatus};
use dpds_controller::telemetry::TelemetrySource;

