/// A valid ConfigDto JSON: Normal delay `mean_ns`/`std_ns`, no loss, and NO limiter stage
/// (the limiter is optional; see [`cfg_full`] for all three stages).
pub fn cfg_json(mean_ns: f64, std_ns: f64) -> Value {
    json!({
        "buffer_capacity": 100000,
        "reordering": false,
        "delayer": {
            "distribution": "NormalDistribution",
            "mean_ns": mean_ns,
            "std_ns": std_ns,
            "activate_correlation": false,
            "half_life_period_ns": 1000000.0,
            "initialization_rate_pps": 15000000.0
        },
        "loss_model": { "type": "Random", "p": 0.0 }
    })
}

/// [`cfg_json`] plus a limiter stage (`Spacer`, `rate_bps`): all three stages present.
pub fn cfg_full(mean_ns: f64, std_ns: f64, rate_bps: f64) -> Value {
    let mut c = cfg_json(mean_ns, std_ns);
    c["limiter"] = json!({ "mode": "Spacer", "rate_bps": rate_bps });
    c
}

/// A config with no stage at all: only the buffer.
pub fn cfg_bare() -> Value {
    json!({ "buffer_capacity": 100000, "reordering": false })
}

pub fn cfg_dto(mean_ns: f64, std_ns: f64) -> ConfigDto {
    serde_json::from_value(cfg_json(mean_ns, std_ns)).expect("cfg_json must deserialize")
}

pub fn dto_from(v: Value) -> ConfigDto {
    serde_json::from_value(v).expect("config JSON must deserialize")
}

/// A link of a start body: `ingress` -> `egress` with the default config (Normal 1 ms /
/// 0.1 ms). A link in a start body has no `id` and no `worker` (cores are automatic).
pub fn link(ingress: &str, egress: &str) -> Value {
    json!({
        "ingress": ingress, "egress": egress,
        "config": cfg_json(1.0e6, 1.0e5),
    })
}

/// Like [`link`] with an explicit config JSON.
pub fn link_cfg(ingress: &str, egress: &str, config: Value) -> Value {
    json!({ "ingress": ingress, "egress": egress, "config": config })
}

/// The typed `model::Link` (as the running configuration carries it) of a start-body link and
/// an id, for the tests of the pure functions in `eal`.
pub fn model_link(id: u32, body: &Value) -> Link {
    let mut v = body.clone();
    v["id"] = json!(id);
    serde_json::from_value(v).expect("a link must deserialize into `Link`")
}

/// What a test starts (or validates, or asks hints for): the links of a start body.
#[derive(Clone)]
pub struct Setup {
    pub links: Vec<Value>,
}

impl Default for Setup {
    fn default() -> Setup {
        setup(vec![])
    }
}

impl Setup {
    /// The JSON body of `POST /api/emulation/start`: `{links}` only.
    pub fn body(&self) -> Value {
        json!({ "links": self.links })
    }
}

pub fn setup(links: Vec<Value>) -> Setup {
    Setup { links }
}

/// One harmless vdev hairpin, for hint tests that need "some link" without caring which.
pub fn filler() -> Setup {
    setup(vec![link("net_null9", "net_null9")])
}

pub const NIC0: &str = "0000:17:00.0"; // mlx5, NUMA 0
pub const NIC1: &str = "0000:65:00.0"; // mlx5, NUMA 1
pub const INTEL: &str = "0000:b3:00.0"; // ice, NUMA 1
pub const MGMT: &str = "0000:03:00.0"; // tg3 with the default route

/// Removes every `null` valued object member recursively (so tests do not care
/// whether `None` is serialized as `null` or skipped).
pub fn strip_nulls(v: &Value) -> Value {
    match v {
        Value::Object(m) => Value::Object(
            m.iter()
                .filter(|(_, x)| !x.is_null())
                .map(|(k, x)| (k.clone(), strip_nulls(x)))
                .collect(),
        ),
        Value::Array(a) => Value::Array(a.iter().map(strip_nulls).collect()),
        other => other.clone(),
    }
}

/// Missing or null.
pub fn absent(v: &Value, key: &str) -> bool {
    v.get(key).is_none_or(Value::is_null)
}

pub fn f(v: &Value, key: &str) -> f64 {
    v[key]
        .as_f64()
        .unwrap_or_else(|| panic!("`{key}` is not a number in {v}"))
}

pub fn assert_close(actual: f64, expected: f64) {
    let tol = 1e-6 * expected.abs().max(1.0);
    assert!(
        (actual - expected).abs() <= tol,
        "expected {expected}, got {actual}"
    );
}

