pub struct Reply {
    pub status: u16,
    pub headers: axum::http::HeaderMap,
    pub body: Vec<u8>,
}

impl Reply {
    pub fn json(&self) -> Value {
        serde_json::from_slice(&self.body).unwrap_or_else(|e| {
            panic!(
                "body is not JSON ({e}): status {} body {:?}",
                self.status,
                String::from_utf8_lossy(&self.body)
            )
        })
    }
    pub fn text(&self) -> String {
        String::from_utf8_lossy(&self.body).into_owned()
    }
    /// Asserts the `{"message": "<non-empty>"}` error shape and returns the message.
    pub fn message(&self) -> String {
        let v = self.json();
        let m = v["message"]
            .as_str()
            .unwrap_or_else(|| panic!("error body without string `message`: {v}"));
        assert!(!m.is_empty(), "empty error message");
        m.to_string()
    }
}

pub struct TestApp {
    pub router: axum::Router,
    pub host: FakeHost,
    pub supervisor: Arc<FakeSupervisor>,
    pub telemetry: Arc<FakeTelemetry>,
    pub runtime_dir: PathBuf,
    pub dpds_bin: PathBuf,
}

impl TestApp {
    pub fn new(host: FakeHost) -> TestApp {
        let supervisor = FakeSupervisor::new();
        let telemetry = FakeTelemetry::new();
        let runtime_dir = PathBuf::from("/run/dpds-controller-test");
        let dpds_bin = PathBuf::from("/usr/local/bin/dpds");
        let router = api::router(Deps {
            roots: host.roots(),
            supervisor: supervisor.clone(),
            telemetry: telemetry.clone(),
            dpds_bin: dpds_bin.clone(),
            runtime_dir: runtime_dir.clone(),
            dpds_has_telemetry: true,
            is_root: false,
        });
        TestApp {
            router,
            host,
            supervisor,
            telemetry,
            runtime_dir,
            dpds_bin,
        }
    }

    pub async fn request(&self, method: &str, path: &str, body: Option<Value>) -> Reply {
        self.request_with(method, path, body, &[]).await
    }

    pub async fn request_with(
        &self,
        method: &str,
        path: &str,
        body: Option<Value>,
        headers: &[(&str, &str)],
    ) -> Reply {
        let mut req = axum::http::Request::builder().method(method).uri(path);
        for (k, v) in headers {
            req = req.header(*k, *v);
        }
        let req = match body {
            Some(b) => req
                .header("content-type", "application/json")
                .body(axum::body::Body::from(b.to_string())),
            None => req.body(axum::body::Body::empty()),
        }
        .unwrap();
        let r = send(&self.router, req).await;
        self.host.exec().assert_read_only();
        r
    }

    /// A request with an arbitrary content type (None = no header) and raw body bytes.
    pub async fn request_raw(
        &self,
        method: &str,
        path: &str,
        content_type: Option<&str>,
        body: Vec<u8>,
    ) -> Reply {
        let mut req = axum::http::Request::builder().method(method).uri(path);
        if let Some(ct) = content_type {
            req = req.header("content-type", ct);
        }
        send(
            &self.router,
            req.body(axum::body::Body::from(body)).unwrap(),
        )
        .await
    }

    pub async fn get(&self, path: &str) -> Reply {
        self.request("GET", path, None).await
    }
    pub async fn post(&self, path: &str, body: Value) -> Reply {
        self.request("POST", path, Some(body)).await
    }

    /// `POST /api/emulation/start` with `setup` as the body.
    pub async fn start(&self, setup: &Setup) -> Reply {
        self.post("/api/emulation/start", setup.body()).await
    }

    /// `POST /api/emulation/start` with these links.
    pub async fn start_links(&self, links: Vec<Value>) -> Reply {
        self.start(&setup(links)).await
    }

    /// Starts `links` and asserts the 202; returns the body.
    pub async fn start_ok(&self, links: Vec<Value>) -> Value {
        let r = self.start_links(links).await;
        assert_eq!(r.status, 202, "{}", r.text());
        r.json()
    }

    /// `POST /api/emulation/validate`.
    pub async fn validate(&self, setup: &Setup) -> Reply {
        self.post("/api/emulation/validate", setup.body()).await
    }
}

/// One request through `router`, with an optional JSON body.
pub async fn call(router: &axum::Router, method: &str, path: &str, body: Option<Value>) -> Reply {
    let req = axum::http::Request::builder().method(method).uri(path);
    let req = match body {
        Some(b) => req
            .header("content-type", "application/json")
            .body(axum::body::Body::from(b.to_string())),
        None => req.body(axum::body::Body::empty()),
    }
    .unwrap();
    send(router, req).await
}

/// Sends one request through `router` and collects the reply.
pub async fn send(router: &axum::Router, req: axum::http::Request<axum::body::Body>) -> Reply {
    use tower::ServiceExt;
    let resp = router.clone().oneshot(req).await.unwrap();
    let status = resp.status().as_u16();
    let headers = resp.headers().clone();
    let body = http_body_util::BodyExt::collect(resp.into_body())
        .await
        .unwrap()
        .to_bytes()
        .to_vec();
    Reply {
        status,
        headers,
        body,
    }
}

/// GET `path` on a router that is not wrapped in a `TestApp`.
pub async fn router_get(router: &axum::Router, path: &str) -> Reply {
    let req = axum::http::Request::builder()
        .method("GET")
        .uri(path)
        .body(axum::body::Body::empty())
        .unwrap();
    send(router, req).await
}

